mapper.update:
UPDATE product_demand_owner_time
SET is_deleted = 1, modify_man_id = #{operatorId}, modify_man = #{operator}, modify_date = NOW()
WHERE is_deleted = 0
AND product_demand_id = #{productDemandId}
AND resource_type = #{resourceType}

mapper.select:
SELECT product_demand_group_id AS groupId, resource_type AS resourceType, SUM(resource_time) AS totalTime FROM product_demand_owner_time WHERE is_deleted = 0 AND product_demand_group_id IN
#{gid}
GROUP BY product_demand_group_id, resource_type
